from PIL import Image,ImageDraw,ImageChops

UPPER=[(858,700),(903,641),(916,620),(906,600),(961,560),(958,542),(1040,480),(1046,450),(1070,445),(1060,423),(1234,294),(1245,314),(1328,243),(1350,256),(1405,210),(1424,232),(1468,188),(1487,204),(1421,256),(1434,269),(1343,350),(1358,364),(1336,386),(1347,400),(1260,459),(1244,446),(1223,469),(1200,457),(1155,494),(1146,485),(1072,547),(1058,534),(1011,578),(998,568),(966,606),(993,624),(972,645),(958,631),(927,664),(909,659),(878,703)]
