LOWER=[(835,751),(843,725),(868,741),(885,731),(949,762),(969,765),(1000,782),(1031,791),(1062,810),(1081,804),(1120,829),(1142,826),(1160,844),(1180,835),(1215,857),(1244,862),(1257,887),(1275,884),(1285,902),(1314,901),(1330,919),(1350,922),(1364,940),(1340,950),(1303,930),(1297,938),(1233,907),(1221,922),(1195,908),(1184,917),(1158,897),(1149,905),(1107,875),(1081,866),(1050,850),(1020,843),(993,824),(966,817),(941,802),(918,797),(890,781),(857,772)]

def point(x,y):return (round((x-820)/20),round((y-160)/20))

def masks(size):
    silhouette=Image.new('L',(64,64));draw=ImageDraw.Draw(silhouette)
    for polygon in [UPPER,MIDDLE,LOWER]:draw.polygon([point(x,y) for x,y in polygon],fill=255)
    frame=Image.new('RGBA',(64,64));d=ImageDraw.Draw(frame)
    def polygon(coords,color):d.polygon([point(x,y) for x,y in coords],fill=color)
    # 上翼的厚重翼根、偏置长骨架和横向卡扣；外端星海保持裸露。
    polygon([(858,700),(877,660),(920,620),(916,601),(959,567),(947,550),(1053,476),(1080,484),(1109,460),(1160,415),(1190,425),(1127,487),(1139,501),(1067,551),(1054,538),(1005,581),(995,566),(966,607),(987,624),(972,640),(958,627),(928,665),(913,657),(879,703)],'#E1DBE8')
    polygon([(975,535),(1233,299),(1245,319),(1011,552)],'#EEEAF1')
    polygon([(1036,486),(1062,462),(1105,501),(1082,522)],'#F3F0F3')
    polygon([(1108,444),(1129,426),(1164,458),(1146,476)],'#D4C6DC')
    polygon([(1160,414),(1265,334),(1281,355),(1180,432)],'#AF8FCB')
    polygon([(1007,517),(1030,498),(1044,513),(1020,533)],'#E78CCD')
    polygon([(1178,374),(1203,351),(1220,366),(1195,388)],'#DE73C3')
    polygon([(1286,400),(1318,370),(1335,386),(1305,416)],'#EAA4D6')
    polygon([(901,631),(934,602),(954,618),(920,648)],'#A98BCC')
    # 中翼只在根部与上缘铺设阶梯骨架，末端为宽阔的星海。
    polygon([(858,737),(916,704),(950,676),(982,681),(987,660),(1047,656),(1050,638),(1109,639),(1110,619),(1171,621),(1172,583),(1205,585),(1209,623),(1158,648),(1118,642),(1108,670),(1050,664),(1046,691),(994,686),(969,711),(918,722),(916,741)],'#EFE6EF')
    polygon([(986,681),(1048,687),(1051,664),(1110,670),(1115,641),(1165,650),(1207,625),(1221,622),(1204,649),(1170,661),(1123,657),(1106,681),(1056,678),(1052,705),(996,696)],'#DB9ED2')
    polygon([(940,727),(995,728),(993,710),(1008,710),(1008,729),(1123,735),(1121,714),(1144,715),(1146,750),(1063,746),(1061,765),(1012,760),(1014,778),(992,776),(988,749),(945,746)],'#E3DAE7')
    # 下翼缩短、向中翼收拢，白色条带主要落在下缘。
    polygon([(835,751),(844,731),(867,746),(874,737),(900,753),(893,770),(940,787),(944,803),(969,809),(972,821),(1062,857),(1066,844),(1124,880),(1114,894),(1060,868),(1025,854),(994,837),(960,824),(935,809),(903,792),(882,780),(856,772)],'#EDE8EF')
    polygon([(916,781),(938,770),(978,790),(970,805)],'#B6A0CE')
    polygon([(1084,854),(1129,876),(1120,890),(1082,871)],'#DE9BCD')
    polygon([(1235,859),(1270,879),(1261,895),(1230,879)],'#9672C6')
    # 截去任何超出轮廓的描线，核心是余下的连续星海区域。
    frame.putalpha(ImageChops.multiply(frame.getchannel('A'),silhouette))
    core=ImageChops.subtract(silhouette,frame.getchannel('A'))
    return frame.resize((size,size),Image.Resampling.NEAREST),core.resize((size,size),Image.Resampling.NEAREST)

def bright_points(size):
    return [(round((x-820)/20*size/64),round((y-160)/20*size/64)) for x,y in [(1301,370),(1264,744),(1175,493)]]
